package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.jobs.ApiRuntimeTelemetry;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class ApiWindowWatermarkTest {
 static final Instant START=Instant.parse("2026-01-01T00:10:00Z");static final String EPOCH="00000000-0000-4000-8000-000000000001",OTHER="00000000-0000-4000-8000-000000000002";static final Key KEY=new Key("OPS-09","java","fictional-api");static final OperationalRuleEngine ENGINE=new OperationalRuleEngine();
 static ApiWindow value(int minute,long requests,long errors,long p95){Instant end=START.plusSeconds(minute/5*300L);return new ApiWindow(new ApiRuntimeTelemetry.Evidence(EPOCH,START.minusSeconds(1000),end.minusSeconds(300),end,requests,errors,p95==0?0:1,p95,START.plusSeconds(minute*60L)));}
 static State tick(State state,int minute,Reading reading){return ENGINE.sample(state,OperationalRuleEngineTest.config(9),1,START.plusSeconds(minute*60L),reading!=null,reading).state();}
 @Test void warningCountsOnlyTwoActuallyDifferentOriginalWindowsAndCodecRetainsWindowProof(){State state=State.empty(KEY);for(int m=0;m<5;m++){state=tick(state,m,value(m,100,2,0));assertEquals(Status.NORMAL,state.status());assertEquals(1,state.counters().get("rate_windows"));}state=tick(state,5,value(5,100,2,0));assertEquals(Level.WARNING,state.level());assertEquals(2,state.counters().get("rate_windows"));assertEquals(state,OperationalStateCodec.decode(OperationalStateCodec.encode(state)));}
 @Test void damagedSameWindowFactsNativeMarkerRollbackAndSyntheticFallbackCannotBecomeHealthy(){State state=tick(State.empty(KEY),0,value(0,100,10,0));assertEquals(Level.CRITICAL,state.level());State changed=tick(state,1,value(1,100,0,0));assertEquals(Status.TELEMETRY_UNKNOWN,changed.status());assertEquals(Level.CRITICAL,changed.level());assertEquals(state.counters().get("api_end_micros"),changed.counters().get("api_end_micros"));assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,1,new ApiHealth(100,java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO,START)).status());assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,1,value(0,100,10,0)).status());var counters=new HashMap<>(state.counters());counters.remove("api_e3");var damaged=new State(state.key(),state.revision(),state.configurationRevision(),state.status(),state.level(),state.firstSeenAt(),state.lastSeenAt(),state.lastSampleAt(),state.observedValue(),state.threshold(),state.timers(),counters,state.guards(),state.acknowledged(),state.recoveryReady(),state.nextReminderAt(),state.silencedUntil());assertEquals(Status.TELEMETRY_UNKNOWN,tick(damaged,1,value(1,100,10,0)).status());}
 @Test void nativeUnknownCannotCountOldWindowAgainAndNoRequestWindowsCannotResolveOldCritical(){State state=tick(State.empty(KEY),0,value(0,100,2,0));state=tick(state,1,null);assertEquals(1,state.counters().get("api_required"));state=tick(state,2,value(2,100,2,0));assertEquals(0,state.counters().getOrDefault("rate_windows",0L));state=tick(state,5,value(5,100,2,0));assertEquals(1,state.counters().get("rate_windows"));State critical=tick(State.empty(KEY),0,value(0,100,10,0));for(int m=1;m<5;m++)critical=tick(critical,m,value(m,100,10,0));for(int m=5;m<=20;m++){critical=tick(critical,m,value(m,0,0,0));assertEquals(Level.CRITICAL,critical.level());}}
 @Test void actualHealthyWindowsKeepOriginalTenMinuteRecoveryAndP95WarningUsesExactNanos(){State state=tick(State.empty(KEY),0,value(0,100,10,0));for(int m=1;m<5;m++)state=tick(state,m,value(m,100,10,0));for(int m=5;m<15;m++){state=tick(state,m,value(m,100,0,0));assertEquals(Level.CRITICAL,state.level());}state=tick(state,15,value(15,100,0,0));assertEquals(Status.RESOLVED,state.status());State lock=State.empty(KEY);for(int m=0;m<=5;m++)lock=tick(lock,m,value(m,100,0,500000001));assertEquals(Level.WARNING,lock.level());}
 @Test void epochChangeNeedsRealLaterBirthAndResetsOriginalTimersRatherThanClearingOldAlarm(){State state=tick(State.empty(KEY),0,value(0,100,10,0));Instant end=START.plusSeconds(600);var forged=new ApiWindow(new ApiRuntimeTelemetry.Evidence(OTHER,START.minusSeconds(1000),end.minusSeconds(300),end,100,0,0,0,end));assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,10,forged).status());var actual=new ApiWindow(new ApiRuntimeTelemetry.Evidence(OTHER,START.plusSeconds(60),end.minusSeconds(300),end,100,0,0,0,end));var newProcess=tick(state,10,actual);assertEquals(Level.CRITICAL,newProcess.level());assertEquals(1,newProcess.counters().get("api_required"));assertEquals(end,newProcess.timers().get("healthy"));assertNotEquals(value(0,100,1,0).toString(),value(0,100,2,0).toString());assertEquals("ApiRuntimeEvidence[redacted]",actual.facts().toString());}
}
